from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.colors import HexColor
from reportlab.lib.pagesizes import letter
INK=HexColor('#0A0A0A');GOLD=HexColor('#C9A227');GOLD2=HexColor('#8A6D14');IV=HexColor('#F7F4EA')
FIRST='Read the attached SOUL, MEMORY, INSTRUCTIONS and AGENT files and the Value Refinery Playbook. Report exactly which files you accessed, summarize MINE in 100 words, and recommend one 10-minute Value Map exercise. Do not claim access you cannot confirm.'
def mk(out,name,sub,steps,notes,files,first=FIRST):
    st=lambda **k:ParagraphStyle('x',**k)
    h1=st(fontName='Times-Roman',fontSize=36,leading=38,textColor=IV);eb=st(fontName='Courier-Bold',fontSize=9,textColor=GOLD,spaceAfter=8)
    sb=st(fontName='Helvetica',fontSize=12,leading=17,textColor=HexColor('#d9d5c8'));h2=st(fontName='Times-Bold',fontSize=17,leading=20,textColor=INK,spaceBefore=14,spaceAfter=6)
    b=st(fontName='Helvetica',fontSize=10.5,leading=15,textColor=INK,spaceAfter=6);num=st(fontName='Courier-Bold',fontSize=12,textColor=GOLD2)
    c=st(fontName='Courier',fontSize=9,leading=12.5,textColor=INK,backColor=HexColor('#F3F0E4'),borderPadding=7,spaceBefore=3,spaceAfter=9)
    def cover(cv,d):
        cv.saveState();cv.setFillColor(INK);cv.rect(0,792-250,612,250,fill=1,stroke=0);cv.setFillColor(GOLD);cv.rect(0,792-253,612,3,fill=1,stroke=0)
        cv.setFont('Courier-Bold',9);cv.drawString(60,60,'MINE  /  THE VALUE REFINERY  /  BY JULIUS TWUM  /  THEVYBE.US/AI');cv.restoreState()
    def later(cv,d):
        cv.saveState();cv.setFillColor(INK);cv.rect(0,792-34,612,34,fill=1,stroke=0);cv.setFillColor(GOLD);cv.setFont('Courier-Bold',8);cv.drawString(60,792-21,'MINE / SETUP / %s'%name.upper());cv.setFont('Courier',8);cv.drawString(60,40,'thevybe.us/ai  -  Mined, not made.');cv.drawString(60,29,'Written Oct 2026. Vendor menus change. Independent of, and not endorsed by, the products named.');cv.restoreState()
    S=[Spacer(1,40),Paragraph('MINE  /  SETUP GUIDE',eb),Paragraph('Run MINE in %s.'%name,h1),Spacer(1,8),Paragraph(sub,sb),Spacer(1,150),Paragraph('Before you start',h2),
       Paragraph('Download the MINE AI Operating Kit from thevybe.us/ai. These files are instructions you load into %s. They are not a hosted agent, API or live integration, and they do not give any assistant access to your accounts. Review every output before you publish or send anything.'%name,b),Paragraph('Files you will use',h2)]
    S+=[Paragraph('- '+f,b) for f in files]+[Paragraph('Setup',h2)]
    for i,t in enumerate(steps,1): S.append(Table([[Paragraph('%02d'%i,num),Paragraph(t,b)]],colWidths=[34,440],style=TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,-1),.4,GOLD),('BOTTOMPADDING',(0,0),(-1,-1),6)])))
    S+=[Paragraph('First message to send',h2),Paragraph(first,c),Paragraph('Notes',h2)]+[Paragraph('- '+n,b) for n in notes]
    S+=[Paragraph('Then run the five stages in order: Mine, Grade, Refine, Forge, Move. Cite your own evidence, treat unclear rights as blocked, and ask for a preview before anything is sent, published, paid or uploaded.',b),Paragraph('Want it done with you? Request a Value Refinery Session on Instagram, @juicebigfellow, or book R3D Reel at thevybe.us/r3d.',b)]
    SimpleDocTemplate(out,pagesize=letter,leftMargin=60,rightMargin=60,topMargin=60,bottomMargin=70,title='MINE Setup: %s'%name,author='Julius Twum').build(S,onFirstPage=cover,onLaterPages=later)
D='assets/mine/guides/'
WS=['MINE_AGENT_WORKSPACE.zip (SOUL, IDENTITY, AGENTS, USER, MEMORY, TOOLS, HEARTBEAT, BOOTSTRAP)','Your agent\'s current files (back them up first)']
mk(D+'MINE_Setup_Hermes.pdf','Hermes Agent (offline)','Local-first agent. SOUL, MEMORY and USER files you control, skills, and a local model option.',
['Install Hermes Agent from Nous Research and run its setup (hermes setup). For offline use, point it at a local model server such as Ollama and choose a local model.','Turn off or replace any web search provider you do not want online. An offline agent can only read files you give it.','Back up your current files. Then copy SOUL.md from the MINE Agent Workspace to ~/.hermes/SOUL.md (the persona slot).','Copy MEMORY.md and USER.md to ~/.hermes/memories/. Hermes limits MEMORY.md to about 2,200 characters and USER.md to about 1,375, and the workspace versions are sized to fit. Fill in USER.md.','Skills: MINE skills use the open Agent Skills format. Copy the skills folders from the kit into Hermes\' skills location, or run its /learn command on the folder.','Start a new session (edits load at session start), send the first message below and run TEST_PROMPTS.md from the kit.'],
['Paths and limits come from Hermes documentation and guides and can change by version. Confirm at hermes-agent.nousresearch.com/docs.','Hermes can write its own skills after complex tasks. Read them before you trust them.','Require approval before it sends, posts, pays or runs commands.'],WS)
mk(D+'MINE_Setup_Muse.pdf','Muse (Meta)','Replace Muse\'s soul and memory with your own MINE soul and memory, built from your assessment.',
['First, finish the free self-assessment at thevybe.us/ai#audit and generate your Value Map.','Under the Value Map press Copy my SOUL (Muse). Open Muse and find its soul file or persona settings. Back up what is there, select all, paste, save.','Press Copy my MEMORY (Muse). Open Muse\'s memory file, back it up, select all, paste, save. This memory holds your asset, buyer, rights, grade and next 72-hour move, so Muse starts from your facts, not generic ones.','Add IDENTITY.md and AGENTS.md from the MINE Agent Workspace if Muse lets you edit more files. Keep Meta\'s purchase approvals and the activity log on.','Start a new chat so the files reload, then send the first message below.','If you cannot edit the files: paste START_PROMPT.md as your first message, then paste your MEMORY text into the same chat.','Optional: copy HEARTBEAT.md into a recurring task so Muse checks your 72-hour plan once a day and asks before acting.'],
['Reports disagree on how much of Muse\'s files you can edit in the app, so test it. Edits you make should show up after a new chat.','Muse runs in Meta\'s cloud and training on your data may be on by default; check the setting and opt out if you prefer. Your MEMORY holds your own business details, so paste only what you are comfortable sharing.','Muse can act in your accounts. Give it only the connections you need.','Details change quickly. Check Meta\'s official Muse help pages.'],WS)
mk(D+'MINE_Setup_OpenClaw.pdf','OpenClaw','Open-source personal agent with the full workspace file layout.',
['Install OpenClaw and run its onboarding. Pick the model provider you want, or a local model.','Back up the workspace folder. Copy all MINE Agent Workspace files into it: SOUL.md, IDENTITY.md, AGENTS.md, USER.md, MEMORY.md, TOOLS.md, HEARTBEAT.md and BOOTSTRAP.md.','Fill in USER.md. TOOLS.md documents limits only; it does not grant access, so set real permissions in the agent configuration.','HEARTBEAT.md runs when the agent wakes (every 30 minutes by default). Keep it short and use isolated sessions to save tokens.','Start a new session, send the first message below and run the kit TEST_PROMPTS.md.'],
['Long workspace files can be trimmed when loaded. Keep each one lean.','Check docs.openclaw.ai for the current layout.'],WS)
mk(D+'MINE_Setup_Dots.pdf','OpenAI Dots','Always-on agent in OpenAI\'s cloud. Standing instructions, not editable memory files.',
['Open your dot in ChatGPT. Dots keeps memory on OpenAI\'s side and it is not an editable file, so keep your own copy of MEMORY.md.','Send a standing instruction built from the MINE SOUL.md and AGENTS.md: the five stages, the six veins, the evidence labels and the approval rules.','Tell it to ask before it buys, sends, books or posts anything, and to hand off to you for money decisions.','Add your 72-hour plan as a recurring task so it checks in once a day.','Resetting or deleting a dot removes its memory. Re-send the standing instruction if that happens.'],
['Dots is rolling out gradually and plans and features change. Check OpenAI\'s current help pages.','Use the workspace files as a reference. The hosted agent may not load them.'],['SOUL.md and AGENTS.md (condense into a standing instruction)','Your own MEMORY.md copy'],
first='Standing instruction: act as MINE Coach. Use five stages (Mine, Grade, Refine, Forge, Move) and six veins (Story, Skill, Proof, Access, Archive, Systems). Label facts VERIFIED, OWNER-REPORTED, UNVERIFIED or PLANNED. Ask before you buy, send, book, post or upload anything.')
